/////////////////////////////////////////////////////////////////////////////
// cMotTskWnd message handlers

LONG cMotTskWnd::MotionMessage(UINT uiMessage, LONG lParam)
{
	short l_sAxis = LOWORD(lParam);

	switch (uiMessage) {
	case MM_DONE:		// 軸の正常停止
		StageMTAxisMotionComplete(l_sAxis, 0);
		m_strMMessage[l_sAxis] = "MM_DONE";
		break;
	case MM_STOPPED:	// 軸の強制停止(エラー等ではありません)
		StageMTAxisMotionComplete(l_sAxis, 1);
		m_strMMessage[l_sAxis] = "MM_STOPPED";
		break;
	case MM_FAILURE:	// 軸の異常終了
		StageMTAxisMotionComplete(l_sAxis, 2);
		m_strMMessage[l_sAxis] = "MM_FAILURE";
		break;
/* added 2009.11.11 hmenjo MotSys 軸タイムアウト ---------- { ---------- */
	case MM_TIMEOUT:	/* 軸の軸の移動タイムアウト	*/
		StageMTAxisMotionComplete(l_sAxis, 2);
		m_strMMessage[l_sAxis] = "MM_TIMEOUT";
		StageMTSetMotSysErr(uiMessage);
		break;
/* added 2009.11.11 hmenjo MotSys 軸タイムアウト ---------- } ---------- */
	case 111:	// 通信(Read)システムエラー発生
	case 112:	// 通信(Read)リトライアウト１発生
	case 113:	// 通信(Read)リトライアウト２発生
	case 121:	// 通信(Read2)システムエラー発生
	case 122:	// 通信(Read2)リトライアウト１発生
	case 123:	// 通信(Read2)リトライアウト２発生
	case 131:	// 通信(Write)システムエラー発生
	case 132:	// 通信(Write)リトライアウト発生
		StageMTSetMotSysComErr(uiMessage);
		break;
	case 1:		// ステージコントローラの WD エラーが発生
	case 2:		// システムエラー色々
	case 3:		// 軸アラーム色々
	case 4:		// 初期化完了フラグが０にならなかった
	case 5:		// DIO エラー
	case 6:		// サーボ ON/OFF エラー
	case 7:		// 非常停止 エラー
		StageMTSetMotSysErr(uiMessage);
		break;
	case 8:		// 原点復帰 エラー	(未使用)
	default:	// 未定義エラー
		StageMTSetMotSysErr(uiMessage);
		break;
	}

	InvalidateRect(NULL, TRUE);    // ask for update of diagnostic info.
	return 0L;
}

void cMotTskWnd::OnTimer(UINT nIDEvent)
{
	switch (nIDEvent) {
	case TIMER1_ID:
		InvalidateRect(NULL, TRUE);    // ask for update of diagnostic info.
		break;
	case TIMER2_ID:
		KillTimer(nIDEvent);
		if (0 != m_bCloseReq) {
			m_bCloseReq = FALSE;
			KillTimer(TIMER1_ID);
			PostMessage(WM_CLOSE, 0, 0);
		}
		break;
	default:
		break;
	}

	//	InvalidateRect(NULL, TRUE);    // ask for repaint
}

void cMotTskWnd::OnPaint()
{
	CPaintDC	dc(this);
	TEXTMETRIC	tm;
	TCHAR		l_tszStr[80];

	// select the font and get the associated text metrics
	dc.SelectStockObject (ANSI_FIXED_FONT);
	dc.GetTextMetrics	 (&tm);
	UINT CyChar = tm.tmHeight + tm.tmExternalLeading;
	UINT CxChar = tm.tmMaxCharWidth;

	// Display the raw stage positions and the last message received
	int i;
	for (WORD i = 0; i < AXIS_NUM; i++) {
		_stprintf(l_tszStr, _T("[%u]: %11ld,  %s"), i, m_Pos[i], m_strMMessage[i]);
		dc.TextOut(CxChar, CyChar * (i + 1), l_tszStr);
	}
	_stprintf(l_tszStr, _T("MotSys Com Error : %d"), StageMTGetMotSysComErr());
	dc.TextOut(CxChar, CyChar * (i + 1), l_tszStr);
	_stprintf(l_tszStr, _T("MotSys Error     : %d"), StageMTGetMotSysErr());
	dc.TextOut(CxChar, CyChar * (i + 2), l_tszStr);
}

void cMotTskWnd::OnClose()
{
	// TODO: この位置にメッセージ ハンドラ用のコードを追加するかまたはデフォルトの処理を呼び出してください

	KillTimer(TIMER1_ID);
	KillTimer(TIMER2_ID);

	CFrameWnd::OnClose();
}

